/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  --ink: #202923;
  --ink-soft: #455149;
  --paper: #f7f6f1;
  --white: #ffffff;
  --forest: #294638;
  --forest-dark: #1c3328;
  --rust: #bd714d;
  --sand: #e9e5da;
  --muted: #777e76;
  --line: rgba(32, 41, 35, 0.15);
  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Arial, sans-serif;
  --container: 1160px;
  --gutter: clamp(22px, 5vw, 76px);
  --section-space: clamp(76px, 10vw, 132px);
  --radius: 3px;
}

/* RESET */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--rust);
  outline-offset: 5px;
}

::selection {
  background: var(--forest);
  color: var(--white);
}

/* TYPOGRAPHY */
h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--ink);
}

h1,
h2 {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.045em;
  line-height: 1.08;
}

h1 {
  font-size: clamp(46px, 7.2vw, 92px);
}

h2 {
  font-size: clamp(36px, 5vw, 62px);
}

h3 {
  font-family: var(--font-display);
  font-size: clamp(23px, 2.5vw, 30px);
  font-weight: 400;
  line-height: 1.2;
}

p {
  color: var(--ink-soft);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--rust);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.19em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 1px;
  background: currentColor;
  content: "";
}

.lead {
  max-width: 610px;
  font-size: clamp(17px, 1.7vw, 20px);
  line-height: 1.75;
}

.text-light {
  color: rgba(255, 255, 255, 0.83);
}

/* SHARED LAYOUT */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section-heading {
  max-width: 740px;
  margin-bottom: 48px;
}

.section-heading h2 {
  margin-bottom: 22px;
}

.section-heading p {
  max-width: 590px;
  margin-bottom: 0;
  font-size: 17px;
}

.accent-line {
  width: 54px;
  height: 3px;
  margin-block: 28px;
  background: var(--rust);
}

/* HEADER & NAVIGATION */
.site-header {
  position: relative;
  z-index: 20;
  min-height: 88px;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  flex-shrink: 0;
}

.brand-mark {
  display: grid;
  width: 45px;
  height: 45px;
  place-items: center;
  background: var(--forest);
  color: var(--white);
}

.brand-mark img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brand-name {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 21px;
  line-height: 1.1;
}

.brand-description {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(18px, 3vw, 38px);
}

.primary-nav a {
  position: relative;
  color: var(--ink-soft);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  transition: color 180ms ease;
}

.primary-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: -7px;
  left: 0;
  height: 1px;
  background: var(--rust);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 180ms ease;
}

.primary-nav a:not(.button):hover {
  color: var(--forest);
}

.primary-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

/* BUTTONS */
.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 23px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--forest);
  color: var(--white);
  cursor: pointer;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.11em;
  line-height: 1.3;
  text-align: center;
  text-transform: uppercase;
  transition:
    background 180ms ease,
    color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.button:hover {
  background: var(--forest-dark);
  transform: translateY(-2px);
}

.button-light {
  border-color: var(--white);
  background: var(--white);
  color: var(--forest-dark);
}

.button-light:hover {
  border-color: var(--sand);
  background: var(--sand);
  color: var(--ink);
}

.button-outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button-outline:hover {
  background: var(--white);
  color: var(--forest-dark);
}

.button-arrow {
  font-size: 17px;
  line-height: 1;
}

/* FULL-BLEED HERO */
.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - 88px));
  align-items: center;
  overflow: hidden;
  background: var(--forest-dark);
  isolation: isolate;
  color: var(--white);
}

.hero-media {
  position: absolute;
  z-index: -2;
  inset: 0;
}

.hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero::after {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(18, 32, 24, 0.88) 0%,
      rgba(18, 32, 24, 0.69) 44%,
      rgba(18, 32, 24, 0.16) 100%
    ),
    linear-gradient(
      0deg,
      rgba(18, 32, 24, 0.42),
      transparent 45%
    );
  content: "";
}

.hero-content {
  width: min(760px, 76%);
  padding-block: clamp(90px, 12vw, 160px);
  color: var(--white);
}

.hero .eyebrow {
  color: #e6ad8e;
}

.hero h1 {
  max-width: 780px;
  margin-bottom: 25px;
  color: var(--white);
}

.hero h1 em {
  color: #e8b89d;
  font-weight: 400;
}

.hero-copy {
  max-width: 535px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, 0.88);
  font-size: clamp(16px, 1.7vw, 19px);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 48px;
  color: rgba(255, 255, 255, 0.85);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.hero-note::before {
  width: 35px;
  height: 1px;
  background: var(--rust);
  content: "";
}

/* INTRODUCTION */
.intro-section {
  background: var(--paper);
}

.intro-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: center;
  gap: clamp(45px, 9vw, 120px);
}

.intro-copy h2 {
  max-width: 510px;
}

.intro-copy p {
  max-width: 540px;
  margin-bottom: 20px;
}

.intro-copy .button {
  margin-top: 15px;
}

.intro-visual {
  position: relative;
  min-height: 480px;
}

.intro-visual img {
  width: 100%;
  height: 480px;
  object-fit: cover;
  object-position: center;
}

.intro-caption {
  position: absolute;
  right: -22px;
  bottom: 25px;
  max-width: 235px;
  padding: 22px 25px;
  background: var(--forest);
  color: var(--white);
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.12);
}

.intro-caption strong {
  display: block;
  margin-bottom: 5px;
  font-family: var(--font-display);
  font-size: 25px;
  font-weight: 400;
}

.intro-caption span {
  color: rgba(255, 255, 255, 0.78);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* EXPERIENCE STATEMENT */
.experience-band {
  padding-block: 48px;
  background: var(--forest);
  color: var(--white);
}

.experience-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 55px;
}

.experience-item {
  display: flex;
  align-items: center;
  gap: 20px;
}

.experience-number {
  color: #e6ad8e;
  font-family: var(--font-display);
  font-size: clamp(43px, 5vw, 62px);
  line-height: 1;
  white-space: nowrap;
}

.experience-label {
  max-width: 170px;
  color: rgba(255, 255, 255, 0.88);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.5;
}

.experience-divider {
  width: 1px;
  height: 60px;
  background: rgba(255, 255, 255, 0.3);
}

/* PROJECT WORK */
.work-section {
  background: #eeece4;
}

.work-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 40px;
}

.work-heading .section-heading {
  margin-bottom: 45px;
}

.work-heading .work-intro {
  max-width: 330px;
  margin-bottom: 52px;
  color: var(--ink-soft);
  font-size: 14px;
}

.work-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  grid-template-rows: 310px 310px;
  gap: 20px;
}

.work-item {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: var(--sand);
}

.work-item:first-child {
  grid-row: span 2;
}

.work-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 450ms ease;
}

.work-item:hover img {
  transform: scale(1.035);
}

.work-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 48px 28px 23px;
  background: linear-gradient(
    0deg,
    rgba(19, 32, 24, 0.88),
    rgba(19, 32, 24, 0)
  );
  color: var(--white);
}

.work-caption span {
  display: block;
  margin-bottom: 5px;
  color: #e8b89d;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.work-caption h3 {
  margin-bottom: 0;
  color: var(--white);
  font-size: 25px;
}

/* HOW WE WORK */
.approach-section {
  background: var(--paper);
}

.approach-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: start;
  gap: clamp(50px, 10vw, 130px);
}

.approach-intro {
  position: sticky;
  top: 35px;
}

.approach-intro h2 {
  max-width: 480px;
}

.approach-intro p {
  max-width: 420px;
}

.approach-list {
  border-top: 1px solid var(--line);
}

.approach-step {
  display: grid;
  grid-template-columns: 65px 1fr;
  gap: 22px;
  padding-block: 29px;
  border-bottom: 1px solid var(--line);
}

.approach-step-number {
  color: var(--rust);
  font-family: var(--font-display);
  font-size: 29px;
  line-height: 1.2;
}

.approach-step h3 {
  margin-bottom: 8px;
}

.approach-step p {
  max-width: 460px;
  margin-bottom: 0;
  font-size: 14px;
}

/* PRIMARY ESTIMATE CTA */
.estimate-section {
  position: relative;
  overflow: hidden;
  padding-block: clamp(75px, 9vw, 112px);
  background: var(--forest-dark);
  color: var(--white);
}

.estimate-section::before {
  position: absolute;
  top: 0;
  right: 0;
  width: 36%;
  height: 100%;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
  content: "";
  pointer-events: none;
}

.estimate-inner {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 55px;
}

.estimate-copy {
  max-width: 690px;
}

.estimate-copy .eyebrow {
  color: #e6ad8e;
}

.estimate-copy h2 {
  margin-bottom: 18px;
  color: var(--white);
}

.estimate-copy p {
  max-width: 530px;
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.8);
}

.estimate-actions {
  display: flex;
  flex-shrink: 0;
  flex-direction: column;
  align-items: flex-start;
  gap: 13px;
}

.estimate-actions .button {
  min-width: 205px;
}
