/* CSS PART 2 OF 2 */

/* CONTACT & CONVERSION */
.contact-section {
  padding-block: var(--section-space);
  background: var(--paper);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: start;
  gap: clamp(45px, 8vw, 105px);
}

.contact-copy h2 {
  max-width: 460px;
}

.contact-copy > p {
  max-width: 410px;
}

.contact-methods {
  display: grid;
  gap: 17px;
  margin-top: 38px;
}

.contact-method {
  display: flex;
  align-items: center;
  gap: 15px;
}

.contact-method-icon {
  display: grid;
  width: 45px;
  height: 45px;
  flex-shrink: 0;
  place-items: center;
  background: var(--sand);
  color: var(--forest);
  font-size: 18px;
}

.contact-method-label {
  display: block;
  margin-bottom: 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.contact-method a {
  color: var(--forest);
  font-size: 15px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.contact-method a:hover {
  color: var(--rust);
}

.contact-form {
  padding: clamp(25px, 4vw, 48px);
  background: var(--white);
  border: 1px solid var(--line);
}

.contact-form h3 {
  margin-bottom: 9px;
  font-size: 30px;
}

.form-intro {
  margin-bottom: 30px;
  color: var(--muted);
  font-size: 13px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 21px 18px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field-full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.055em;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 51px;
  padding: 13px 14px;
  border: 1px solid #d9d9d1;
  border-radius: 2px;
  background: #fcfcfa;
  color: var(--ink);
  font-size: 14px;
  transition: border-color 160ms ease, background 160ms ease;
}

.form-field textarea {
  min-height: 135px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #888e86;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--forest);
  background: var(--white);
}

.form-submit {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px;
  margin-top: 25px;
}

.form-submit p {
  max-width: 235px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

/* FOOTER */
.site-footer {
  padding-top: 55px;
  background: #192c22;
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 45px;
  padding-bottom: 48px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-description {
  color: rgba(255, 255, 255, 0.58);
}

.footer-brand-copy {
  max-width: 360px;
  margin-top: 18px;
  color: rgba(255, 255, 255, 0.69);
  font-size: 13px;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 30px;
  padding-top: 12px;
}

.footer-links a {
  color: rgba(255, 255, 255, 0.82);
  font-size: 12px;
  font-weight: 700;
}

.footer-links a:hover {
  color: #e8b89d;
}

.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px;
  padding-block: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
  color: rgba(255, 255, 255, 0.55);
  font-size: 10px;
}

/* ACCESSIBLE MOBILE MENU */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: transparent;
  color: var(--forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* TABLET */
@media (max-width: 900px) {
  :root {
    --gutter: 30px;
    --section-space: 85px;
  }

  .primary-nav {
    gap: 17px;
  }

  .primary-nav a {
    font-size: 11px;
  }

  .header-inner {
    gap: 16px;
  }

  .brand-name {
    font-size: 19px;
  }

  .brand-description {
    font-size: 8px;
  }

  .intro-layout,
  .approach-layout {
    gap: 45px;
  }

  .intro-visual,
  .intro-visual img {
    min-height: 410px;
    height: 410px;
  }

  .experience-inner {
    gap: 25px;
  }

  .work-grid {
    grid-template-rows: 270px 270px;
  }

  .contact-layout {
    grid-template-columns: 1fr 1.2fr;
    gap: 35px;
  }

  .footer-main {
    gap: 30px;
  }
}

/* MOBILE NAVIGATION AND LAYOUT */
@media (max-width: 700px) {
  :root {
    --gutter: 23px;
    --section-space: 72px;
  }

  html {
    scroll-padding-top: 75px;
  }

  .site-header {
    min-height: 74px;
  }

  .header-inner {
    position: relative;
    min-height: 74px;
    flex-wrap: wrap;
    gap: 0;
  }

  .brand {
    gap: 10px;
  }

  .brand-mark {
    width: 39px;
    height: 39px;
  }

  .brand-name {
    font-size: 18px;
  }

  .brand-description {
    font-size: 7px;
  }

  .menu-toggle {
    display: flex;
  }

  .primary-nav {
    display: none;
    position: absolute;
    z-index: 30;
    top: calc(100% - 1px);
    right: 0;
    left: 0;
    max-height: calc(100svh - 85px);
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    overflow-y: auto;
    padding: 9px 18px;
    border: 1px solid var(--line);
    background: var(--paper);
    box-shadow: 0 14px 25px rgba(20, 35, 26, 0.12);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a {
    display: block;
    width: 100%;
    padding: 13px 4px;
    border-bottom: 1px solid var(--line);
    font-size: 12px;
  }

  .primary-nav a::after {
    display: none;
  }

  .primary-nav .button {
    width: 100%;
    margin-block: 10px;
    border: 0;
  }

  /* HERO */
  .hero {
    min-height: 690px;
    min-height: min(760px, calc(100svh - 74px));
    align-items: flex-end;
  }

  .hero-media img {
    object-position: 60% center;
  }

  .hero::after {
    background:
      linear-gradient(
        0deg,
        rgba(18, 32, 24, 0.93) 0%,
        rgba(18, 32, 24, 0.73) 48%,
        rgba(18, 32, 24, 0.2) 100%
      );
  }

  .hero-content {
    width: 100%;
    padding-block: 85px 58px;
  }

  .hero h1 {
    max-width: 580px;
    font-size: clamp(44px, 11vw, 66px);
  }

  .hero-copy {
    max-width: 460px;
    font-size: 16px;
  }

  .hero-note {
    margin-top: 30px;
    font-size: 9px;
  }

  .hero-actions {
    align-items: stretch;
  }

  .hero-actions .button {
    flex: 1 1 190px;
  }

  /* INTRO */
  .intro-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .intro-visual,
  .intro-visual img {
    min-height: 0;
    height: 360px;
  }

  .intro-caption {
    right: 12px;
    bottom: 12px;
  }

  /* EXPERIENCE */
  .experience-band {
    padding-block: 34px;
  }

  .experience-inner {
    grid-template-columns: 1fr 1fr;
    gap: 25px 15px;
  }

  .experience-divider {
    display: none;
  }

  .experience-item {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .experience-number {
    font-size: 43px;
  }

  .experience-label {
    font-size: 11px;
  }

  /* PROJECTS */
  .work-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 0;
  }

  .work-heading .section-heading {
    margin-bottom: 12px;
  }

  .work-heading .work-intro {
    max-width: 500px;
    margin-bottom: 28px;
  }

  .work-grid {
    grid-template-columns: 1fr;
    grid-template-rows: none;
    gap: 14px;
  }

  .work-item,
  .work-item:first-child {
    grid-row: auto;
    height: 330px;
  }

  .work-item img {
    object-position: center;
  }

  /* APPROACH */
  .approach-layout {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .approach-intro {
    position: static;
  }

  .approach-step {
    grid-template-columns: 43px 1fr;
    gap: 14px;
    padding-block: 24px;
  }

  .approach-step-number {
    font-size: 25px;
  }

  /* ESTIMATE */
  .estimate-section::before {
    display: none;
  }

  .estimate-inner {
    align-items: flex-start;
    flex-direction: column;
    gap: 30px;
  }

  .estimate-actions {
    width: 100%;
    flex-direction: row;
    flex-wrap: wrap;
  }

  .estimate-actions .button {
    flex: 1 1 190px;
  }

  /* CONTACT */
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 38px;
  }

  .contact-methods {
    gap: 14px;
    margin-top: 26px;
  }

  .contact-form {
    padding: 25px 20px;
  }

  .form-grid {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .form-field-full {
    grid-column: auto;
  }

  .form-submit {
    align-items: stretch;
    flex-direction: column;
  }

  .form-submit .button {
    width: 100%;
  }

  /* FOOTER */
  .footer-main {
    flex-direction: column;
    gap: 24px;
    padding-bottom: 32px;
  }

  .footer-links {
    gap: 14px 22px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 5px;
  }
}

/* SMALL MOBILE */
@media (max-width: 390px) {
  :root {
    --gutter: 18px;
  }

  .brand-name {
    font-size: 16px;
  }

  .brand-description {
    font-size: 6.5px;
    letter-spacing: 0.1em;
  }

  .hero h1 {
    font-size: 43px;
  }

  .hero-actions .button {
    flex-basis: 100%;
  }

  .work-item,
  .work-item:first-child {
    height: 280px;
  }

  .work-caption {
    padding: 40px 19px 18px;
  }

  .experience-inner {
    gap: 22px 10px;
  }

  .contact-form {
    padding: 22px 16px;
  }
}

/* KEYBOARD FOCUS */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--rust);
  outline-offset: 4px;
}

.primary-nav a:focus-visible {
  position: relative;
  z-index: 2;
}

/* REDUCED MOTION */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .work-item:hover img,
  .button:hover {
    transform: none;
  }
}
